function glyph(name) { return glyphs[name]; }

// SMuFL glyph for a clef kind index (ScoreModel.clefKind order).
function clefGlyph(kind) {
    switch (kind) {
    case 0: return glyphs.gClef;          // French violin
    case 1: return glyphs.gClef;          // Treble
    case 2: case 3: case 4: case 5: case 6:
        return glyphs.cClef;              // C clefs
    case 7: case 8: case 9: return glyphs.fClef; // F clefs
    default: return glyphs.unpitchedPercussionClef1;
    }
}

// Notehead glyph for a NoteValue int (-1=breve .. 7=128th).
function notehead(value) {
    if (value <= -1) return glyphs.noteheadBreve;
    if (value === 0) return glyphs.noteheadWhole;
    if (value === 1) return glyphs.noteheadHalf;
    return glyphs.noteheadBlack;
}

// Flag glyph for value>=3 (eighth and shorter), or null.
function flag(value, up) {
    if (value < 3) return null;
    const v = Math.min(value, 7);
    const names = [null, null, null,
        up ? "flag8thUp" : "flag8thDown",
        up ? "flag16thUp" : "flag16thDown",
        up ? "flag32ndUp" : "flag32ndDown",
        up ? "flag64thUp" : "flag64thDown",
        up ? "flag128thUp" : "flag128thDown"];
    return glyphs[names[v]];
}

// Rest glyph for a NoteValue int.
function rest(value) {
    switch (value) {
    case -1: return glyphs.restBreve;
    case 0: return glyphs.restWhole;
    case 1: return glyphs.restHalf;
    case 2: return glyphs.restQuarter;
    case 3: return glyphs.rest8th;
    case 4: return glyphs.rest16th;
    case 5: return glyphs.rest32nd;
    case 6: return glyphs.rest64th;
    default: return glyphs.rest128th;
    }
}

// Time-signature digit glyphs for a number.
function digits(n) {
    return String(n).split("").map(d => glyphs["timeSig" + d]);
}
